  vec2 p = (gl_FragCoord.xy * 2.0 - uResolution) /
           min(uResolution.x, uResolution.y);

  float scale = max(0.1, uZoom);
  p *= scale;

  vec2 rz = vec2(0.0);
  float stepMul = mix(0.0, 0.1, clamp(uDetail, 0.0, 1.0));

